session_start();require_once 'database.php';
if(empty($_SESSION['2fa_pending_user'])){header('Location: login.php');exit;}
function b32d2($s){$a='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$bits='';foreach(str_split(strtoupper($s)) as $c){$i=strpos($a,$c);if($i===false)continue;$bits.=str_pad(decbin($i),5,'0',STR_PAD_LEFT);} $o='';for($i=0;$i+8<=strlen($bits);$i+=8)$o.=chr(bindec(substr($bits,$i,8)));return $o;}
function totp2($secret,$time=null){$key=b32d2($secret);$counter=pack('N*',0).pack('N*',intdiv($time??time(),30));$h=hash_hmac('sha1',$counter,$key,true);$o=ord($h[19])&15;$b=((ord($h[$o])&127)<<24)|((ord($h[$o+1])&255)<<16)|((ord($h[$o+2])&255)<<8)|(ord($h[$o+3])&255);return str_pad((string)($b%1000000),6,'0',STR_PAD_LEFT);}
$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$code=trim($_POST['code']??'');$q=$pdo->prepare('SELECT secret FROM two_factor WHERE user_id=? AND enabled_at IS NOT NULL');$q->execute([(int)$_SESSION['2fa_pending_user']]);$secret=$q->fetchColumn();$ok=false;for($i=-1;$i<=1;$i++)if($secret&&hash_equals(totp2($secret,time()+$i*30),$code))$ok=true;if($ok){$id=(int)$_SESSION['2fa_pending_user'];session_regenerate_id(true);$_SESSION['user_id']=$id;$_SESSION['name']=$_SESSION['2fa_pending_name'];$_SESSION['role']=$_SESSION['2fa_pending_role'];$_SESSION['logged_in']=true;unset($_SESSION['2fa_pending_user'],$_SESSION['2fa_pending_name'],$_SESSION['2fa_pending_role']);$pdo->prepare('UPDATE users SET last_login=CURRENT_TIMESTAMP WHERE id=?')->execute([$id]);header('Location: '.($_SESSION['role']==='admin'?'admin.php':'dashboard.php'));exit;}else$error='Invalid verification code.';}
